/** Face points per outfit, as [x, y]: eyes, mouth, the back ear, tusks beside the mouth, and the nose above it. */
export type Face = { eyes: readonly Point[]; mouth: readonly Point[]; ear: readonly Point[]; tusks: readonly Point[]; nose: readonly Point[] };
/** Glow points drawn on top (`heroFX`): lantern and orb centres, the blade glint column and its row span, dagger tips. */
export type OutfitFx = { lantern?: Point; orb?: Point; blade?: readonly [number, number, number]; tips?: readonly Point[] };
export type Outfit = { rows: Grid; pal: Readonly<Record<string, string>>; face: Face; fx: OutfitFx; masked?: true };

